from fastapi import FastAPI, Depends, Response
from typing import Annotated

app = FastAPI()

def modify_response():
    return Response(content="Modified", media_type="text/plain")

@app.get("/")
def endpoint(response: Response = Depends(modify_response)):
    return {"message": "hello"}

def test_response_dependency():
    from fastapi.testclient import TestClient
    client = TestClient(app)
    client.get("/")

if __name__ == "__main__":
    try:
        test_response_dependency()
        print("Success")
    except AssertionError as e:
        print(f"Caught expected AssertionError: {e}")
        raise e
    except Exception as e:
        print(f"Caught unexpected exception: {e}")
        raise e
